"""Quota-constrained follow-up plan with a checkable probe certificate."""
import time

from flow import Flow
from protocols import probe_script

SOURCE = 0
SINK = 1
PD_EDGE_LIMIT = 20000
PD_COST_LIMIT = 400
PD_SECONDS = 20.0


def _pairs(context, active):
    """Map every request id to the offers that may serve it."""
    requests = context['requests']
    offers = context['offers']
    leases = context['leases']
    pairs = {}
    for oid, offer in offers.items():
        network = offer['network']
        low = int(network.network_address)
        high = int(network.broadcast_address)
        service = offer['service']
        when = offer['time']
        listed = pairs
        for rid in offer['requests']:
            request = requests[rid]
            if not active.get(rid, False):
                continue
            if request['service'] != service:
                continue
            if request['at'] > when or when >= leases[request['lease']]['end']:
                continue
            if not low <= request['address'] <= high:
                continue
            bucket = listed.get(rid)
            if bucket is None:
                listed[rid] = [oid]
            else:
                bucket.append(oid)
    return pairs


def _classes(requests, pairs):
    """Merge requests that are interchangeable for every constraint."""
    classes = {}
    for rid in sorted(pairs):
        request = requests[rid]
        key = (request['lease'], request['at'], request['service'],
               request['group'], request['address'])
        bucket = classes.get(key)
        if bucket is None:
            classes[key] = [rid]
        else:
            bucket.append(rid)
    return classes


def _depths(paths, wanted):
    order = sorted(wanted, key=lambda node: len(paths[node]))
    return order


def _build(context, pairs, classes):
    leases = context['leases']
    requests = context['requests']
    offers = context['offers']
    rnodes = context['request_quotas']
    onodes = context['offer_quotas']
    rpaths = context['request_paths']
    opaths = context['offer_paths']

    used_offers = {}
    for rid, oids in pairs.items():
        for oid in oids:
            used_offers[oid] = offers[oid]

    wanted_r = set()
    demand = {}
    for key, rids in classes.items():
        weight = len(rids)
        group = requests[rids[0]]['group']
        for node in rpaths[group]:
            wanted_r.add(node)
            demand[node] = demand.get(node, 0) + weight
    wanted_o = set()
    supply = {}
    for oid, offer in used_offers.items():
        weight = offer['capacity']
        for node in opaths[offer['group']]:
            wanted_o.add(node)
            supply[node] = supply.get(node, 0) + weight

    eff_r = {}
    for node in _depths(rpaths, wanted_r):
        capacity = min(rnodes[node]['capacity'], demand[node])
        parent = rnodes[node]['parent']
        if parent is not None:
            capacity = min(capacity, eff_r[parent])
        eff_r[node] = capacity
    eff_o = {}
    for node in _depths(opaths, wanted_o):
        capacity = min(onodes[node]['capacity'], supply[node])
        parent = onodes[node]['parent']
        if parent is not None:
            capacity = min(capacity, eff_o[parent])
        eff_o[node] = capacity

    keys = sorted(classes)
    class_index = {}
    for position, key in enumerate(keys):
        class_index[key] = position
    offer_ids = sorted(used_offers)
    offer_index = {}
    for position, oid in enumerate(offer_ids):
        offer_index[oid] = position
    rnode_ids = sorted(wanted_r)
    rnode_slot = {}
    for position, node in enumerate(rnode_ids):
        rnode_slot[node] = position
    onode_ids = sorted(wanted_o)
    onode_slot = {}
    for position, node in enumerate(onode_ids):
        onode_slot[node] = position

    base = 2
    class_base = base
    offer_base = class_base + len(keys)
    rnode_base = offer_base + len(offer_ids)
    onode_base = rnode_base + len(rnode_ids)
    total = onode_base + len(onode_ids)
    network = Flow(total)

    for node in rnode_ids:
        parent = rnodes[node]['parent']
        if parent is None:
            network.add(SOURCE, rnode_base + rnode_slot[node], eff_r[node], 0)
        else:
            network.add(rnode_base + rnode_slot[parent], rnode_base + rnode_slot[node],
                        eff_r[node], 0)
    for node in onode_ids:
        parent = onodes[node]['parent']
        if parent is None:
            network.add(onode_base + onode_slot[node], SINK, eff_o[node], 0)
        else:
            network.add(onode_base + onode_slot[node], onode_base + onode_slot[parent],
                        eff_o[node], 0)
    for key in keys:
        group = requests[classes[key][0]]['group']
        network.add(rnode_base + rnode_slot[group], class_base + class_index[key],
                    len(classes[key]), 0)
    for oid in offer_ids:
        offer = used_offers[oid]
        group = offer['group']
        room = min(offer['capacity'], eff_o[group])
        network.add(offer_base + offer_index[oid], onode_base + onode_slot[group], room, 0)
    links = []
    for rid, oids in pairs.items():
        request = requests[rid]
        key = (request['lease'], request['at'], request['service'],
               request['group'], request['address'])
        for oid in oids:
            offer = used_offers[oid]
            room = min(offer['capacity'], eff_o[offer['group']])
            if room <= 0:
                continue
            links.append((class_index[key], offer_index[oid], oid, offer['cost'], room))
    edges = {}
    for position, (class_position, offer_position, oid, cost, room) in enumerate(links):
        index = network.add(class_base + class_position, offer_base + offer_position, 1, cost)
        edges[index] = (class_position, offer_position)
    return {'network': network, 'keys': keys, 'classes': classes,
            'offer_ids': offer_ids, 'class_base': class_base,
            'offer_base': offer_base, 'edges': edges, 'links': links}


def _networkx(total, edges, class_base, offer_base, nedge):
    import networkx as nx
    graph = nx.DiGraph()
    graph.add_nodes_from(range(total))
    for u, v, cap, cost in edges:
        if cap > 0:
            graph.add_edge(u, v, capacity=cap, weight=cost)
    value = nx.maximum_flow_value(graph, SOURCE, SINK)
    if value <= 0:
        return 0, 0, {}
    residual = nx.DiGraph(graph)
    residual.add_node(SOURCE, demand=-value)
    residual.add_node(SINK, demand=value)
    cost, flow = nx.network_simplex(residual)
    return value, cost, flow


def solve(context, active):
    """Return the maximum-cardinality minimum-cost follow-up certificate."""
    requests = context['requests']
    services = context['services']
    pairs = _pairs(context, active)
    if not pairs:
        return {'resolved': 0, 'cost': 0, 'assignments': []}
    classes = _classes(requests, pairs)
    model = _build(context, pairs, classes)
    network = model['network']
    links = model['links']
    distinct = len({link[3] for link in links})
    middles = len(links)
    answer = None
    if distinct == 1:
        answer = network.solve(SOURCE, SINK)
    elif distinct <= PD_COST_LIMIT or middles <= PD_EDGE_LIMIT:
        deadline = time.monotonic() + PD_SECONDS
        answer = network.solve(SOURCE, SINK, deadline=deadline,
                               phase_limit=100000)
        if answer is None:
            answer = _networkx_fallback(model)
    else:
        answer = _networkx_fallback(model)
    if answer is None:
        answer = network.solve(SOURCE, SINK)
    total, cost = answer[0], answer[1]
    flow = answer[2] if len(answer) > 2 else None
    assignments = _extract(model, network, flow)
    scripts = {}
    for service_id in set(request['service'] for request in requests.values()):
        scripts[service_id] = probe_script(services[service_id])
    records = []
    for rid, oid in assignments:
        send, finish = scripts[requests[rid]['service']]
        records.append({'request': rid, 'offer': oid, 'send': send, 'finish': finish})
    records.sort(key=lambda row: row['request'])
    return {'resolved': len(records), 'cost': cost, 'assignments': records}


def _networkx_fallback(model):
    network = model['network']
    edges = []
    for u in range(network.n):
        for index in network.graph[u]:
            if index % 2 == 0:
                capacity = network.cap[index]
                if capacity > 0:
                    edges.append((u, network.to[index], capacity, network.cst[index]))
    try:
        return _networkx(network.n, edges, model['class_base'], model['offer_base'],
                         len(edges))
    except Exception:
        return None


def _extract(model, network, flow):
    """Turn solved edge flows into (request, offer) obligations."""
    classes = model['classes']
    keys = model['keys']
    offer_ids = model['offer_ids']
    result = []
    if flow is None:
        for index, (class_position, offer_position) in model['edges'].items():
            amount = network.used(index)
            if amount:
                _assign(result, classes, keys, offer_ids, class_position,
                        offer_position, amount)
    else:
        class_base = model['class_base']
        offer_base = model['offer_base']
        for source, targets in flow.items():
            if not (class_base <= source < class_base + len(keys)):
                continue
            class_position = source - class_base
            for target, amount in targets.items():
                if amount and offer_base <= target < offer_base + len(offer_ids):
                    _assign(result, classes, keys, offer_ids, class_position,
                            target - offer_base, amount)
    return result


def _assign(result, classes, keys, offer_ids, class_position, offer_position, amount):
    rids = classes[keys[class_position]]
    oid = offer_ids[offer_position]
    for position in range(amount):
        result.append((rids[position], oid))
